//! The business-module skeleton — everything a fork's module carries:
//!
//! * [`proto`] / [`DESCRIPTOR_BYTES`] / [`pool`] — the module's own
//!   contract: prost types + pbjson serde, the buf-produced annotated
//!   closure, the process-global pool. Generated by the module's
//!   build.rs over its own `api/` workspace (biz-proto-build).
//! * [`gen`] — the route/error/trait/mount surface the same generator
//!   emits for the admin contract, sliced to this module's tree.
//! * [`pack`] — the module's route pack over the admin edge
//!   (`admin_api::server::edge`): the same bind/gate/audit stack the
//!   admin surface rides, parameterized with this module's pool,
//!   mounts, and audit face.
//! * [`data`] / [`services`] / [`seed`] / [`migration`] — the tenant-
//!   scoped entity + repo (via the exported `repo_shell!` macro), the
//!   service implementation, the idempotent boot seeds, and the
//!   module's own migration chain.
//!
//! The assembly binary (`backend/apps/platform`) mounts this pack
//! beside the admin surface; nothing here touches the admin tree.

use std::sync::Arc;

/// Generated prost types + pbjson serde impls for the module contract.
///
/// Generated code carries no doc comments and is not held to hand-written lint
/// standards; the contract prose lives in the .proto sources.
#[allow(missing_docs)]
#[allow(clippy::all)]
pub mod proto {
    include!(concat!(env!("OUT_DIR"), "/proto_include.rs"));
}

/// The module's proto compile closure as raw `FileDescriptorSet` bytes —
/// annotations included — compiled by the build script from the module's
/// own contract tree and the buf.lock-pinned dependency modules
/// (`api/buf.yaml`).
pub static DESCRIPTOR_BYTES: &[u8] =
    include_bytes!(concat!(env!("OUT_DIR"), "/annotated_descriptor.bin"));

/// The decoded descriptor pool. The pool is immutable and process-global;
/// decoding happens once.
pub fn pool() -> &'static prost_reflect::DescriptorPool {
    static POOL: std::sync::OnceLock<prost_reflect::DescriptorPool> = std::sync::OnceLock::new();
    POOL.get_or_init(|| {
        prost_reflect::DescriptorPool::decode(DESCRIPTOR_BYTES)
            .expect("annotated_descriptor.bin must decode")
    })
}

/// Generated route/error/trait/mount surface — do not edit; regenerate by
/// building.
#[allow(missing_docs)]
#[allow(clippy::all)]
pub mod gen {
    include!(concat!(env!("OUT_DIR"), "/template_gen.rs"));
}

/// Handwritten table accessors over the generated annotation tables —
/// the module-local mirror of the admin contract's tables module.
pub mod tables {
    /// Resolves a (package, reason) pair against the module's generated
    /// `(errors.code)` annotation table. Callers must collapse `None`
    /// into the Unknown error shape (500, empty reason).
    pub fn error_status(package: &str, reason: &str) -> Option<i32> {
        crate::gen::error_tables::ERROR_STATUS
            .iter()
            .find(|(p, r, _)| *p == package && *r == reason)
            .map(|(_, _, s)| *s)
    }
}

include!("auth_free.rs");

/// The module's error envelope helper: reason → the module error
/// table's HTTP status (`StatusError::new`) and the `<Reason>` literal
/// (the admin state helper's mirror over the module's own table).
pub fn status_error(
    reason: &'static str,
    message: impl Into<String>,
) -> admin_api::state::StatusError {
    let status = tables::error_status("notice.service.v1", reason).unwrap_or(500);
    rushwind_http_binding::envelope::StatusError::new(status, reason, message)
}

/// The module's not-found error (404 + `NOT_FOUND`).
pub fn not_found(what: &str) -> admin_api::state::StatusError {
    status_error("NOT_FOUND", format!("{what} not found"))
}

/// The module `PagingRequest` → the admin-contract `PagingRequest`
/// conversion: the two compile the same BSR pagination proto with the
/// same prost version, so the wire bytes transcode verbatim. The
/// exported `repo_shell!`'s paged list takes the admin type (its
/// `PagingInput` impl lives in the admin contract crate), so the
/// module services convert at the boundary.
pub fn paging_of(
    req: &proto::pagination::PagingRequest,
) -> Result<admin_api::proto::proto::pagination::PagingRequest, admin_api::state::StatusError> {
    use prost::Message as _;
    admin_api::proto::proto::pagination::PagingRequest::decode(req.encode_to_vec().as_slice())
        .map_err(|e| admin_api::state::internal_error(format!("paging transcode: {e}")))
}

/// The module's audit route rows: (method, path, operation_id) — the
/// audit layer resolves operations against these. Kept as a literal so
/// the audit face is static; `tests/gen_surface.rs` pins the rows to
/// the generated ROUTES table so they cannot drift.
pub static AUDIT_ROWS: &[(&str, &str, &str)] = &[
    (
        "GET",
        "/template/v1/notices",
        "/notice.service.v1.NoticeService/List",
    ),
    (
        "GET",
        "/template/v1/notices/{id}",
        "/notice.service.v1.NoticeService/Get",
    ),
    (
        "POST",
        "/template/v1/notices",
        "/notice.service.v1.NoticeService/Create",
    ),
    (
        "PUT",
        "/template/v1/notices/{id}",
        "/notice.service.v1.NoticeService/Update",
    ),
    (
        "DELETE",
        "/template/v1/notices/{id}",
        "/notice.service.v1.NoticeService/Delete",
    ),
];

pub mod data;
pub mod migration;
pub mod seed;
pub mod services;

/// The module's route pack over the admin edge: the same per-route
/// stack (bind outermost, auth gate inside), the same audit layer, no
/// docs face (the module ships no OpenAPI asset). Mounted beside the
/// admin surface by the assembly binary
/// (`backend/apps/platform`).
pub fn pack(
    state: Arc<admin_api::state::AppState>,
) -> impl Fn(
    serde_json::Value,
    rushwind_bootstrap::RouteInput,
) -> Result<rushwind_bootstrap::RouteSurface, rushwind_bootstrap::BootstrapError>
       + Send
       + Sync
       + 'static {
    admin_api::server::edge::pack_with(move |_settings| {
        Ok(admin_api::server::edge::edge_router(
            &state,
            admin_api::server::edge::EdgePack {
                pool: pool(),
                subtypes: REGISTERED_SUBTYPES,
                mounts: vec![Box::new({
                    let state = Arc::clone(&state);
                    move |router_pub: axum::Router,
                          router_gate: axum::Router,
                          wrap: &admin_api::server::edge::Wrap|
                          -> (axum::Router, axum::Router) {
                        crate::gen::mounts::mount_notice_service(
                            router_pub,
                            router_gate,
                            Arc::new(crate::services::NoticeService {
                                state: Arc::clone(&state),
                            }),
                            wrap,
                        )
                    }
                })],
                docs: None,
                audit: Some(admin_api::audit::AuditFace::from_rows(AUDIT_ROWS)),
                extras: vec![],
            },
        ))
    })
}

/// The deployment's registered codec subtypes — the same register the
/// admin surface mounts under (the compatibility spec §2.1 set).
const REGISTERED_SUBTYPES: &[&str] = &["json", "proto", "x-www-form-urlencoded"];
